// src/lib/fabric.ts — the browser talks to the edge function only
import { supabase } from "@/integrations/supabase/client";

export async function fabricQuery<T>(query: string, variables: Record<string, unknown> = {}): Promise<T> {
  const { data, error } = await supabase.functions.invoke("fabric-graphql", { body: { query, variables } });
  if (error) throw error;
  if (data?.errors?.length) throw new Error(data.errors[0].message);
  return data.data as T;
}

per_user_alternative.source:
// Per-user alternative: each user signs in with Microsoft and queries as themselves.
// Entra app: delegated permission Power BI Service -> GraphQLApi.Execute.All; each user (or a group) needs
// "Run Queries and Mutations" on the API. Supabase Auth: Azure provider configured with the same app.
await supabase.auth.signInWithOAuth({
  provider: "azure",
  options: { scopes: "https://analysis.windows.net/powerbi/api/GraphQLApi.Execute.All offline_access email", redirectTo: window.location.origin },
});
// after the redirect: session.provider_token is the user's token for Fabric; send it with every query
const { data: { session } } = await supabase.auth.getSession();
await supabase.functions.invoke("fabric-graphql", {
  body: { query, variables },
  headers: { "x-fabric-token": session?.provider_token ?? "" },
});

